shader:
struct FilterUniforms {
  resolution: vec2f,
  opacity: f32,
  time: f32,
  params: array<vec4f, 16>,
};
@group(0) @binding(0) var<uniform> u: FilterUniforms;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var inputSampler: sampler;

struct VSOut {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
};

@vertex fn vs_main(@builtin(vertex_index) vi: u32) -> VSOut {
  let positions = array<vec2f, 4>(vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(-1.0, 1.0), vec2f(1.0, 1.0));
  let uvs = array<vec2f, 4>(vec2f(0.0, 1.0), vec2f(1.0, 1.0), vec2f(0.0, 0.0), vec2f(1.0, 0.0));
  var out: VSOut;
  out.position = vec4f(positions[vi], 0.0, 1.0);
  out.uv = uvs[vi];
  return out;
}

@fragment fn fs_main(in: VSOut) -> @location(0) vec4f {
  let c = textureSample(inputTex, inputSampler, in.uv);
  let brightness = u.params[0].x;
  let contrast = u.params[1].x;
  var rgb = (c.rgb - vec3f(0.5)) * contrast + vec3f(0.5) + vec3f(brightness);
  rgb = clamp(rgb, vec3f(0.0), vec3f(1.0));
  return vec4f(rgb, c.a);
}
